<script setup lang="ts">import { useRoute,useRouter } from 'vue-router';import { mediaUrl } from '../api/http';const route=useRoute(),router=useRouter();const path=String(route.query.src||''),src=mediaUrl(path),video=route.query.type==='video',filename=String(route.query.filename||'video');const downloadUrl=`${import.meta.env.VITE_API_BASE||'/api'}/media/download?path=${encodeURIComponent(path)}`</script>
<template><main class="viewer" @click="router.back()"><button class="back" @click.stop="router.back()">‹</button><a v-if="video" class="download" :href="downloadUrl" :download="filename" @click.stop>下载原视频</a><video v-if="video" :src="src" controls autoplay playsinline @click.stop/><img v-else :src="src"></main></template>
<style scoped>.viewer{position:fixed;inset:0;background:#000;display:flex;align-items:center;justify-content:center}.viewer img,.viewer video{max-width:100%;max-height:100%;object-fit:contain}.back{position:fixed;top:18px;left:18px;z-index:2;width:40px;height:40px;border:0;border-radius:50%;background:rgba(255,255,255,.2);color:#fff;font-size:32px;line-height:30px}.download{position:fixed;top:20px;right:18px;z-index:2;padding:9px 14px;border-radius:20px;background:rgba(255,255,255,.2);color:#fff;text-decoration:none;font-size:14px;backdrop-filter:blur(8px)}</style>
